import {initialState,transition,restoreState,canConfirm,STORAGE_KEY} from './model.js';

const root=document.querySelector('#main');
const announcement=document.querySelector('#announcement');
let state=initialState();
try {state=restoreState(sessionStorage.getItem(STORAGE_KEY));} catch {}
let view=['current','reasoning'].includes(location.hash.slice(1))?location.hash.slice(1):'prototype';
let screen='inbox', reviewOpen=false, reviewTab='understanding', kind='scope', draft='', error='';
const escape=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const phaseLabels={request:'Waiting for your input',rechecking:'Re-evaluating understanding',revised:'Revised plan · needs review',agreed:'Understanding confirmed',working:'Working within agreed scope',delivered:'Demo result ready'};
const exampleCorrections={
  scope:'The issue is about desktop signup spacing. Keep every field, sign-up option, and validation rule. Please revise your plan without changing signup behaviour.',
  evidence:'What evidence shows that validation causes the layout problem? Compare your recommendation with the report before proposing a fix.',
  constraint:'Keep this change limited to the desktop signup layout. Do not change the login screen, authentication logic, or mobile experience.'
};
const latest=()=>state.corrections.at(-1);
const button=(text,action,primary=false,extra='')=>`<button class="button${primary?' primary':''}" data-action="${action}" ${extra}>${text}</button>`;
function save(){try{sessionStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{}}
function notify(text){announcement.textContent=text;}
function dispatch(action){const next=transition(state,action);if(next===state)return;state=next;save();render();}
function agentAvatar(){return '<img class="agent-avatar" src="logo.svg" alt="">';}
function tag(text,type=''){return `<span class="tag ${type}">${text}</span>`;}
function toolbar(){return `<div class="app-toolbar"><div class="breadcrumbs"><span class="muted">Zedu</span><span class="chevron">›</span><strong>Issues</strong>${screen==='issue'?'<span class="chevron">›</span><span class="muted">#106</span>':''}</div><button class="text-button" data-action="reset">↺ Reset demo</button></div>`;}
function tabs(){return `<nav class="status-tabs" aria-label="Issue views"><button data-action="inbox" class="${screen==='inbox'?'active':''}">▱ Inbox <span class="count">${['working','delivered'].includes(state.phase)?'0':'1'}</span></button><span class="spacer"></span><button data-action="issue" class="${screen==='issue'?'active':''}">◷ In progress <span class="count">1</span></button><span class="tag">Focused recreation</span></nav>`;}
function inbox(){
  const finished=state.phase==='delivered', active=state.phase==='working';
  return `<div class="inbox-layout"><section><div class="inbox-heading"><h2>${finished?'Result to review':active?'Work in progress':'Need your input'}</h2><span class="count">1</span></div>
    <article class="notification-card"><div class="card-top"><div class="waiting-label ${finished?'green':''}"><span class="status-dot"></span> ${escape(phaseLabels[state.phase]).toUpperCase()}</div>
      <h3>${finished?'The signup layout is ready for your review':active?'A clear plan. Work can move forward.':'Is the agent solving the right problem?'}</h3>
      <p class="issue-ref">#106 · Desktop Sign up screen doesn’t fit in the default window</p>
      <div class="agent-message"><span class="agent-name">NETRUNNER <span class="muted">· sample agent</span></span><p>${state.phase==='request'?'“I can make the form fit by removing the optional fields and simplifying validation. Shall I proceed?”':state.phase==='rechecking'?'“You challenged my interpretation. I need to re-check the report before proposing another approach.”':finished?'“The simulated layout change is ready. Here is what changed, what was checked, and what still needs testing.”':active?'“I’ll change spacing and button layout only, within the plan you approved.”':'“The revised plan preserves all fields, signup options, and validation. Please check that this matches your intent.”'}</p></div>
      <div class="card-actions">${button(finished?'Review demo result ↗':active?'Review progress ↗':'Review understanding ↗','review',true)}<button class="text-button" data-action="issue">Open issue</button></div></div>
      <div class="card-foot"><span class="status-dot"></span> ${active?'Approval applies to plan v'+state.version:finished?'Completion is demonstrated, not a live fix':'Work stays paused until a specific plan is approved.'}</div></article>
    <p class="reset-note">${state.phase==='request'?'Start here: inspect the proposal, challenge its scope, and agree on a better plan.':'Your progress stays in this tab. Reset demo to replay the full exchange.'}</p>
    </section><aside class="inbox-aside"><div class="side-card"><h3>YOUR AGENT</h3><div class="agent-row">${agentAvatar()}<div><strong>Netrunner</strong><small>${escape(phaseLabels[state.phase])}</small></div></div><p class="side-note">${active?'Approved scope: desktop signup layout only.':finished?'Next step: review evidence and accept or question the result.':'Next step: establish what the task means before work continues.'}</p></div><div class="side-card"><h3>THE HUMAN’S ROLE</h3><p class="side-note">You can question the evidence, correct an assumption, or change a constraint. You don’t have to accept the agent’s framing.</p></div><p class="tip"><strong>Small addition, existing home.</strong><br>This proposal extends Ziki’s Inbox and issue conversation. It does not replace the dashboard.</p></aside></div>`;
}
function issue(){return `<button class="text-button back" data-action="inbox">← Back to Inbox</button><div class="issue-layout ${reviewOpen?'with-review':''}"><article class="issue-main"><h2 class="issue-title"><span>#106</span> Desktop Sign up screen doesn’t fit in the default window</h2><div class="tags">${tag('Design')}${tag('Desktop')}${tag('Sample scenario')}</div>
  <section class="content-section"><h3>DESCRIPTION</h3><div class="description-copy"><p>At the desktop app’s default <strong>1280 × 720</strong> window size, the signup form is too tall. Social sign-up options and terms text fall below the visible area.</p><p><strong>Goal:</strong> fit the complete form in the default window by adjusting layout and spacing.</p></div><div class="scope-note">Keep all fields, text, sign-up options, validation, and signup behaviour. The login screen and signup logic are out of scope.</div></section>
  <section class="content-section"><h3>AGENT DECISIONS</h3><div class="decision-summary">${agentAvatar()}<div><strong>Netrunner · ${state.version===1?'proposed approach':'plan v'+state.version}</strong><p>${state.version===1?'Reduce form height by removing optional fields and simplifying validation.':'Layout and spacing only. Keep authentication and signup behaviour unchanged.'}</p>${!reviewOpen?button('Review understanding ↗','review',true):'<span class="small blue">Review is open alongside the issue →</span>'}</div></div></section>
  <section class="content-section"><h3>CONVERSATION</h3><div class="thread-item"><div class="thread-header"><span class="avatar">T</span><strong>Demo teammate</strong><small>Reporter</small></div><p>The signup screen should fit without removing any signup options. Please keep the change limited to layout.</p></div>
  ${state.corrections.map((item,index)=>`<div class="thread-item"><div class="thread-header"><span class="avatar">Y</span><strong>You</strong><small>Correction ${index+1}</small></div><p>${escape(item.text)}</p></div>`).join('')}
  ${state.version>1?`<div class="thread-item"><div class="thread-header">${agentAvatar()}<strong>Netrunner</strong><small>Revised understanding · v${state.version}</small></div><p>The original recommendation changed behaviour outside the requested scope. The revised plan adjusts spacing and social-button layout, preserving all fields and validation.</p></div>`:''}
  ${state.approvedVersion?`<div class="thread-item"><div class="thread-header"><span class="avatar">✓</span><strong>Plan v${state.approvedVersion} approved</strong></div><p>Approval is limited to the revised desktop layout plan. Further material changes require a new review.</p></div>`:''}
  </section></article>${reviewOpen?review():`<aside class="issue-side"><div><p class="section-kicker">STATUS</p>${tag(['working','delivered'].includes(state.phase)?'In progress':'Waiting for input','amber')}</div><div><p class="section-kicker">PEOPLE</p><div class="agent-row">${agentAvatar()}<div><strong>Netrunner</strong><p>Sample contributor</p></div></div></div><div><p class="section-kicker">YOUR CONTROL</p><p>Review the agent’s understanding at any point—not only when it asks a question.</p><br>${button('Review understanding','review',true)}</div></aside>`}</div>`;}
function review(){
  const phaseIndex={request:0,rechecking:1,revised:2,agreed:3,working:3,delivered:4}[state.phase];
  return `<section class="review-panel" aria-labelledby="review-title"><header class="review-header"><div><p class="section-kicker">HUMAN + AGENT REVIEW</p><h2 id="review-title" tabindex="-1">Review understanding</h2><p>#106 · Netrunner · Plan v${state.version}</p></div><button class="icon-button" data-action="close-review" aria-label="Close review panel">×</button></header>
    <div class="review-tabs" role="tablist" aria-label="Review information"><button role="tab" aria-selected="${reviewTab==='understanding'}" class="${reviewTab==='understanding'?'active':''}" id="tab-understanding" aria-controls="review-body" tabindex="${reviewTab==='understanding'?0:-1}" data-tab="understanding">Understanding</button><button role="tab" aria-selected="${reviewTab==='evidence'}" class="${reviewTab==='evidence'?'active':''}" id="tab-evidence" aria-controls="review-body" tabindex="${reviewTab==='evidence'?0:-1}" data-tab="evidence">Evidence</button><button role="tab" aria-selected="${reviewTab==='history'}" class="${reviewTab==='history'?'active':''}" id="tab-history" aria-controls="review-body" tabindex="${reviewTab==='history'?0:-1}" data-tab="history">Changes <span class="count">${state.version-1}</span></button></div>
    <div class="review-content"><div class="phase-track" aria-hidden="true">${Array.from({length:5},(_,i)=>`<span class="${i<=phaseIndex?'done':''}"></span>`).join('')}</div>
    <div class="paused-banner ${['agreed','working','delivered'].includes(state.phase)?'success':''}"><span>${['working','delivered'].includes(state.phase)?'✓':'Ⅱ'}</span> ${escape(phaseLabels[state.phase])}${state.phase==='agreed'?' · not yet authorized':''}</div>
    <div role="tabpanel" id="review-body" aria-labelledby="tab-${reviewTab}">${reviewTab==='evidence'?evidence():reviewTab==='history'?reviewHistory():understanding()}</div>
    ${!['rechecking','delivered'].includes(state.phase)?composer():state.phase==='delivered'?`<div class="composer"><h3>Something still wrong?</h3><p>Reopen the investigation. Prior approval will no longer authorize further work.</p>${button('Question this result','reopen',false)}</div>`:''}
    </div><div class="review-footer"><span>◉</span> Scripted demonstration. Nothing is sent to Ziki.</div></section>`;
}
function understanding(){
  if(state.phase==='rechecking')return `<div class="review-label">YOUR CORRECTION</div>${latest()?`<div class="user-correction"><p>${escape(latest().text)}</p></div>`:''}<div class="understanding-block"><div class="review-label">AGENT ACKNOWLEDGEMENT · SIMULATED</div><p>I need to test my interpretation against the original report and your correction. The proposed action stays paused. I won’t treat this message as approval.</p></div><div class="recheck-card"><h3>What gets re-checked?</h3><p>The requested outcome, the proposed cause, changes outside the agreed scope, and evidence still missing.</p>${button('Run simulated re-check →','recheck',true)}<div class="simulation-note">This sample re-check is pre-written for the signup scenario. It does not run an AI agent or inspect a repository.</div></div>`;
  if(state.phase==='delivered')return result();
  if(state.phase==='working')return `<div class="understanding-block"><div class="review-label">WORKING AGAINST PLAN V${state.version}</div><p>Adjusting desktop signup spacing and the social-button row. Fields, validation, authentication, and the login screen remain outside this plan.</p></div><ul class="plan-list"><li><b>✓</b> Approved plan recorded</li><li><b>◷</b> Demonstrate layout change and verification</li><li><b>○</b> Return the result for human review</li></ul><p class="simulation-note">No real implementation is running. Continue to see the sample completion report, or correct the direction below.</p>${button('Show simulated result →','complete',true)}`;
  let content=`<div class="understanding-block"><div class="review-label">WHAT I THINK THE TASK IS</div><p>Make the complete desktop signup form fit in the default 1280 × 720 window.</p></div>`;
  if(state.phase==='request')return content+`<div class="understanding-block"><div class="review-label">WHAT I OBSERVED</div><p>The report says social sign-up buttons and terms text are cut off. It identifies large fixed gaps in the layout.</p></div><div class="understanding-block"><div class="review-label">MY ASSUMPTION</div><div class="assumption">${tag('Not verified')}<br>There are too many fields and too much validation for this window size.</div></div><div class="understanding-block"><div class="review-label">MY PROPOSED APPROACH</div><ol class="plan-list"><li><b>01</b> Remove optional fields</li><li><b>02</b> Simplify validation</li><li><b>03</b> Recheck whether the form fits</li></ol></div><p class="evidence-warning">Notice the gap: the report requests a layout change; this plan changes signup behaviour.</p>`;
  content+=`<div class="understanding-block"><div class="review-label">WHAT CHANGED IN MY UNDERSTANDING</div><p>The form’s layout is the reported problem. Removing fields or changing validation does not respect the requested scope. The earlier cause was an assumption, not a verified finding.</p></div><div class="version-diff"><div class="removed"><small>REMOVED FROM PLAN V${state.version-1}</small>${state.version===2?'Remove fields and simplify validation.':'Previous layout plan returned for another review.'}</div><div class="added"><small>REVISED PLAN V${state.version}</small>Adjust spacing and the social-button row. Preserve signup behaviour.</div></div><ul class="plan-list"><li><b>01</b> Reduce excessive vertical gaps</li><li><b>02</b> Place social sign-up buttons in a compact row</li><li><b>03</b> Check fit at 1280 × 720 and test smaller/resized windows</li></ul><div class="scope-note">Keep all fields, options, text, validation, and authentication. No login or mobile changes.</div>`;
  if(latest())content+=`<div class="understanding-block" style="margin-top:18px"><div class="review-label">YOUR LATEST DIRECTION</div><div class="user-correction"><p>${escape(latest().text)}</p></div><p class="simulation-note">Free-text corrections are recorded verbatim. This scripted prototype cannot determine whether every custom constraint is satisfied; check the plan and continue the discussion if it does not match.</p></div>`;
  if(state.phase==='agreed')return content+`<div class="recheck-card"><h3>We agree on the direction.</h3><p>Understanding is confirmed. Work is still paused until you authorize this exact plan.</p>${button('Approve revised plan v'+state.version+' →','approve',true)}<p class="simulation-note">Permits only the layout changes above. It does not approve deployment, authentication changes, or a broader redesign.</p></div>`;
  return content+`<div class="composer"><h3>Does this match your intent?</h3><p>Check the revised plan before confirming. Questions and corrections are still welcome.</p><label class="agreement-check"><input type="checkbox" data-check="goal" ${state.confirmed.includes('goal')?'checked':''}> The goal matches the issue.</label><label class="agreement-check"><input type="checkbox" data-check="scope" ${state.confirmed.includes('scope')?'checked':''}> The scope and constraints match my direction.</label><label class="agreement-check"><input type="checkbox" data-check="evidence" ${state.confirmed.includes('evidence')?'checked':''}> I understand the evidence and remaining checks.</label>${button('Confirm shared understanding →','agree',true,canConfirm(state)?'':'disabled')}<p class="simulation-note">Confirmation records understanding. Approval is a separate next step.</p></div>`;
}
function evidence(){return `<div class="review-label">EVIDENCE, NOT HIDDEN REASONING</div><p class="small muted">Reported facts, assumptions, and checks are shown separately. This is not a transcript of an agent’s private reasoning.</p><article class="evidence-card"><h3>01 · The issue report</h3><p>The desktop signup form exceeds the default window. Large fixed gaps are identified as the layout problem.</p><blockquote>Keep the fields, sign-up behaviour, and validation unchanged.</blockquote><small>Paraphrased from the public report · inspected 27 Oct 2026</small><a href="https://ziki.dev/issues/106" target="_blank" rel="noreferrer">Open original issue #106 ↗</a></article><article class="evidence-card"><h3>02 · The mismatch</h3><p>The sample agent recommends removing fields and changing validation. That changes behaviour outside a layout-only request.</p><small>Illustrative agent proposal written for this prototype</small></article><article class="evidence-card"><h3>03 · What is still unverified?</h3><p>No source repository has been inspected here. No layout, authentication, or device tests have actually run. A real agent would need linked screenshots, diffs, and test results.</p><small>Explicit limits of this demonstration</small></article>`;}
function reviewHistory(){return `<div class="review-label">A RECORD YOU CAN FOLLOW</div><div class="evidence-card"><h3>v1 · Original proposal</h3><p>Remove optional fields and simplify validation. No approval granted.</p></div>${state.corrections.map((item,i)=>`<div class="evidence-card"><h3>Correction ${i+1} · You</h3><p>${escape(item.text)}</p></div>`).join('')}${state.version>1?`<div class="evidence-card"><h3>v${state.version} · Revised proposal</h3><p>Layout and spacing only. Keep fields and signup behaviour. ${state.approvedVersion===state.version?'Approved for this version.':'No current approval.'}</p></div>`:''}<p class="simulation-note">Every new correction invalidates prior confirmation and approval. A revised plan needs a fresh review.</p>`;}
function result(){return `<div class="completion"><span class="green">✓ SAMPLE COMPLETION REPORT</span><h3>The layout change is ready for review.</h3><p>This report demonstrates what an agent should return. It is not evidence of an actual fix.</p></div><div class="understanding-block" style="margin-top:20px"><div class="review-label">WHAT CHANGED · SIMULATED</div><ul class="result-list"><li>Reduced fixed vertical spacing</li><li>Placed social sign-up buttons side by side</li><li>Preserved fields, text, and validation</li></ul></div><div class="evidence-card"><h3>Verification report · illustrative</h3><p>Default-window layout: sample pass.<br>Resized-window behaviour: still needs verification.<br>Authentication regression: still needs verification.</p><small>All results above are scripted. No tests against Zedu ran.</small></div><p class="small muted">A real completion would link the exact change and actual verification evidence.</p>${button('Replay this scenario ↺','reset',false)}`;}
function composer(){return `<form class="composer" id="correction-form"><h3>${state.phase==='working'?'Need to redirect the work?':'Question or correct the direction'}</h3><p>${state.phase==='working'?'A correction pauses the simulated work and invalidates its prior approval.':'The agent should explain or revise its interpretation—not just ask you to approve it.'}</p><div class="chips"><button type="button" class="chip ${kind==='scope'?'active':''}" data-kind="scope">That’s outside scope</button><button type="button" class="chip ${kind==='evidence'?'active':''}" data-kind="evidence">Show the evidence</button><button type="button" class="chip ${kind==='constraint'?'active':''}" data-kind="constraint">Add a constraint</button></div><label class="sr-only" for="correction">Your question or correction</label><textarea id="correction" name="correction" maxlength="1000" placeholder="Tell the agent what seems wrong or what it needs to reconsider…" aria-describedby="correction-help">${escape(draft)}</textarea><p id="correction-help" class="simulation-note">Use a suggested correction or write your own. Do not enter sensitive information.</p>${error?`<p class="form-error" role="alert">${error}</p>`:''}<div class="composer-bottom"><small>Recorded locally in this tab</small><button class="button primary" type="submit">Send for re-evaluation ↑</button></div></form>`;}
function currentPattern(){return `<div class="baseline-banner"><strong>Current pattern · focused recreation.</strong> Based on the live issue layout inspected on 27 Oct 2026. This is an explanatory reconstruction, not a complete or pixel-exact copy.</div><div class="app-shell">${toolbar()}<div class="app-body"><div class="issue-layout"><article><h2 class="issue-title"><span>#106</span> Desktop Sign up screen doesn’t fit in the default window</h2><div class="tags">${tag('Design')}${tag('Desktop')}</div><section class="content-section"><h3>DESCRIPTION</h3><p class="description-copy">The report describes layout overflow and a layout-only scope. Its context is available on the issue.</p></section><section class="content-section"><h3>AGENT DECISIONS</h3><div class="decision-summary">${agentAvatar()}<div><strong>Agent · Confirmed</strong><p>A compact verdict summarizes an agent’s decision. The issue also has attributed conversation and activity.</p><span class="small muted">Current pattern recreated for comparison</span></div></div></section><section class="content-section"><h3>CONVERSATION</h3><div class="thread-item"><p>People can read comments and reply. The proposed improvement adds a structured exchange that connects a challenge to a revised understanding, plan version, and new approval.</p></div></section>${button('Try the proposed review →','try',true)}</article><aside class="issue-side"><div><p class="section-kicker">THE OPPORTUNITY</p><p>Make it clear what the agent believes, what changed after a correction, and what the human is approving.</p></div><div><a href="https://ziki.dev/issues/106" target="_blank" rel="noreferrer" class="small">View original issue ↗</a></div></aside></div></div></div>`;}
function reasoning(){return `<article class="reasoning"><header class="reasoning-head"><p class="eyebrow">THE DESIGN REASONING</p><h2>A decision is only useful<br>if we understand the work behind it.</h2><p>A human needs a way to question an agent’s interpretation, check its direction, and correct mistakes before authorizing the next step.</p></header><div class="reasoning-grid"><section class="reason-block"><span class="reason-number">01 / THE PROBLEM</span><h3>“Approve?” can hide a misunderstanding.</h3><p>An agent can ask a clear question about the wrong action. Approving or rejecting alone does not establish whether it has understood the task. A reply thread may contain context, but the agreement and its effect on work can remain unclear.</p></section><section class="reason-block"><span class="reason-number">02 / THE EXISTING HOME</span><h3>Extend the issue, not the dashboard.</h3><p>Ziki’s Inbox already collects requests for human input. Issue details already show agent decisions and conversation. Add a review entry at the request and a review panel beside the issue. The same entry can be available during ongoing agent work.</p></section><section class="reason-block wide"><span class="reason-number">03 / THE INTERACTION</span><h3>Make understanding something both sides can check.</h3><p>The agent separates observations from assumptions. A human can inspect evidence and supply a correction. The agent re-evaluates, shows the revised plan, and asks the human to confirm the direction. Approval then applies to that specific version.</p><div class="rationale-flow"><span>Agent proposal</span><i>→</i><span>Human challenge</span><i>→</i><span>Re-evaluation</span><i>→</i><span>Revised agreement</span><i>→</i><span>Scoped approval</span></div></section><section class="reason-block"><span class="reason-number">04 / WHY THESE DETAILS</span><h3>Corrections must change the workflow.</h3><ul><li>Work stays paused during review.</li><li>Changes are visible, not silently overwritten.</li><li>Understanding and authorization are separate.</li><li>A new correction clears old approval.</li><li>Completion returns with evidence and a way to reopen.</li></ul></section><section class="reason-block"><span class="reason-number">05 / WHAT WE WOULD MEASURE</span><h3>Does it help people steer the work?</h3><p>In a user test, ask someone to spot the scope mismatch, correct it, identify the revised plan, and explain what they approved. Measure completion, misunderstandings, and the time taken. No usability results are claimed here.</p></section><section class="reason-block wide"><span class="reason-number">06 / HONEST SCOPE & ATTRIBUTION</span><h3>A working interaction prototype. A simulated agent.</h3><p>The Inbox and issue styling are inspired by <a href="https://ziki.dev" target="_blank" rel="noreferrer">Ziki</a>. The layout-only scenario is adapted from <a href="https://ziki.dev/issues/106" target="_blank" rel="noreferrer">issue #106</a>; the mistaken proposal, agent responses, and completion report are fictional. Names and personal workspace data are not copied.</p><p>We reviewed <a href="https://ziki-desk.vercel.app/" target="_blank" rel="noreferrer">Michael Churchill’s Ziki Desk</a> as a related prototype. Its decision-focused dashboard helped identify overlap with our earlier idea. This submission focuses on questioning, repairing, and agreeing on an agent’s understanding inside an issue. It does not incorporate Ziki Desk’s code or dashboard.</p><p>The prototype uses browser-tab storage and a scripted state machine. It has no live Ziki API, AI integration, actual code execution, notifications, or permissions enforcement. A production version needs authenticated issue/agent access, linked evidence, plan-version storage, and execution gates on the server.</p><p>Design principles apply to an agent waiting for a person or an agent being redirected. Offline or idle status alone is not proof that an agent is stuck or mistaken.</p></section></div><div style="margin-top:24px">${button('Try the full exchange →','try',true)}</div></article>`;}
function render(){
  document.querySelectorAll('[data-view]').forEach(item=>{const active=item.dataset.view===view;item.classList.toggle('selected',active);item.setAttribute('aria-pressed',String(active));});
  root.innerHTML=view==='reasoning'?reasoning():view==='current'?currentPattern():`<div class="app-shell">${toolbar()}<div class="app-body">${tabs()}${screen==='inbox'?inbox():issue()}</div></div>`;
}
function focusReview(){document.querySelector('#review-title')?.focus({preventScroll:true});if(innerWidth<800)document.querySelector('.review-panel')?.scrollIntoView({behavior:'smooth',block:'start'});}
function setView(next){view=next;history.replaceState(null,'',`#${view}`);render();}
document.querySelectorAll('[data-view]').forEach(item=>item.addEventListener('click',()=>setView(item.dataset.view)));
document.querySelector('.brand').addEventListener('click',event=>{event.preventDefault();setView('prototype');screen='inbox';render();});
root.addEventListener('input',event=>{if(event.target.id==='correction')draft=event.target.value;});
root.addEventListener('change',event=>{if(event.target.dataset.check){dispatch({type:'check',name:event.target.dataset.check,checked:event.target.checked});document.querySelector(`[data-check="${event.target.dataset.check}"]`)?.focus({preventScroll:true});}});
root.addEventListener('submit',event=>{if(event.target.id!=='correction-form')return;event.preventDefault();if(draft.trim().length<8){error='Please write at least 8 characters so the correction has enough context.';render();document.querySelector('#correction')?.focus();return;}const text=draft;draft='';error='';reviewTab='understanding';dispatch({type:'correct',text,kind});notify('Correction recorded. Work is paused for re-evaluation.');focusReview();});
root.addEventListener('click',event=>{
  const target=event.target.closest('button');if(!target)return;
  if(target.dataset.tab){reviewTab=target.dataset.tab;render();document.querySelector(`[data-tab="${reviewTab}"]`)?.focus({preventScroll:true});return;}
  if(target.dataset.kind){kind=target.dataset.kind;draft=exampleCorrections[kind];error='';render();document.querySelector('#correction')?.focus({preventScroll:true});return;}
  const action=target.dataset.action;if(!action)return;
  if(action==='review'){screen='issue';reviewOpen=true;reviewTab='understanding';render();focusReview();}
  else if(action==='issue'){screen='issue';reviewOpen=false;render();}
  else if(action==='inbox'){screen='inbox';reviewOpen=false;render();}
  else if(action==='close-review'){reviewOpen=false;render();root.querySelector('[data-action="review"]')?.focus({preventScroll:true});}
  else if(action==='try'){screen='inbox';reviewOpen=false;setView('prototype');root.scrollIntoView({behavior:'smooth',block:'start'});}
  else if(action==='reset'){state=initialState();draft='';error='';kind='scope';screen='inbox';reviewOpen=false;reviewTab='understanding';save();render();notify('Demo reset. No live work was changed.');}
  else if(['recheck','agree','approve','complete','reopen'].includes(action)){reviewTab='understanding';dispatch({type:action});notify(phaseLabels[state.phase]+'.');focusReview();}
});
root.addEventListener('keydown',event=>{if(event.target.getAttribute('role')!=='tab')return;if(['ArrowRight','ArrowLeft','Home','End'].includes(event.key)){event.preventDefault();const tabs=['understanding','evidence','history'];const next=event.key==='Home'?0:event.key==='End'?2:(tabs.indexOf(reviewTab)+(event.key==='ArrowRight'?1:2))%3;reviewTab=tabs[next];render();document.querySelector(`[data-tab="${reviewTab}"]`)?.focus({preventScroll:true});}});
addEventListener('hashchange',()=>{view=['current','reasoning'].includes(location.hash.slice(1))?location.hash.slice(1):'prototype';render();});
const theme=document.querySelector('#theme');
try{document.documentElement.classList.toggle('light',localStorage.getItem('ziki-understanding-theme')==='light');}catch{}
function syncTheme(){const light=document.documentElement.classList.contains('light');theme.textContent=light?'☾':'☼';theme.setAttribute('aria-label',light?'Switch to dark mode':'Switch to light mode');document.querySelector('meta[name="theme-color"]').content=light?'#f6f8fc':'#0b152b';}
theme.addEventListener('click',()=>{document.documentElement.classList.toggle('light');syncTheme();try{localStorage.setItem('ziki-understanding-theme',document.documentElement.classList.contains('light')?'light':'dark');}catch{}});
syncTheme();render();
